3a15ef7dbb"},{"proname":"multa36_ponte","args":"","types":"","result":"trigger","lang":"plpgsql","prosecdef":true,"provolatile":"v","proparallel":"u","proisstrict":false,"proleakproof":false,"prokind":"f","pronargdefaults":0,"defaults":null,"proconfig":["search_path=pg_catalog, pg_temp","TimeZone=UTC"],"body_hash":"0892fca052994e24430660475289fbd68770b26cbd9d78929737808de6588115"},{"proname":"rpc_capacidades_multa36","args":"","types":"","result":"jsonb","lang":"plpgsql","prosecdef":true,"provolatile":"v","proparallel":"u","proisstrict":false,"proleakproof":false,"prokind":"f","pronargdefaults":0,"defaults":null,"proconfig":["search_path=pg_catalog, pg_temp"],"body_hash":"994c84638c51bc47859f1743a3375886a123ef4a12401a11c9ac3f2b3839548b"},{"proname":"multa36_imutavel","args":"","types":"","result":"trigger","lang":"plpgsql","prosecdef":true,"provolatile":"v","proparallel":"u","proisstrict":false,"proleakproof":false,"prokind":"f","pronargdefaults":0,"defaults":null,"proconfig":["search_path=pg_catalog, pg_temp"],"body_hash":"f830f4960db32f4f657e4404f7c318b0910e4bf13ad1aba73a2df1b74f7ae9da"},{"proname":"multa36_metadata","args":"","types":"","result":"text","lang":"sql","prosecdef":true,"provolatile":"v","proparallel":"u","proisstrict":false,"proleakproof":false,"prokind":"f","pronargdefaults":0,"defaults":null,"proconfig":["search_path=pg_catalog, pg_temp"],"body_hash":"68804c8ee044c8d9776ee2b7749a8e661b3ac53aa5e4cafedd4e1e766e81fec1"},{"proname":"multa36_verificar","args":"","types":"","result":"void","lang":"plpgsql","prosecdef":true,"provolatile":"v","proparallel":"u","proisstrict":false,"proleakproof":false,"prokind":"f","pronargdefaults":0,"defaults":null,"proconfig":["search_path=pg_catalog, pg_temp"],"body_hash":"dbfaceb9994018331bd7308590e9f4cb597c3475452713d9d0cd45c4bd2dd45f"}]$after37$::jsonb;
 SELECT array_agg(DISTINCT f->>'proname') INTO names FROM jsonb_array_elements(expected) f;
 SELECT jsonb_agg(j ORDER BY j->>'proname',j->>'types') INTO actual FROM (
 SELECT jsonb_build_object('proname',p.proname,'args',pg_get_function_identity_arguments(p.oid),'types',oidvectortypes(p.proargtypes),'result',pg_get_function_result(p.oid),'lang',l.lanname,'prosecdef',p.prosecdef,'provolatile',p.provolatile,'proparallel',p.proparallel,'proisstrict',p.proisstrict,'proleakproof',p.proleakproof,'prokind',p.prokind,'pronargdefaults',p.pronargdefaults,'defaults',pg_get_expr(p.proargdefaults,0),'proconfig',to_jsonb(p.proconfig),'body_hash',encode(extensions.digest(p.prosrc,'sha256'),'hex')) j FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.proname=ANY(names)) q;
 SELECT jsonb_agg(f ORDER BY f->>'proname',f->>'types') INTO expected FROM jsonb_array_elements(expected) f;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Postflight37 fonte/config/overload diferente da extensão prevista' USING ERRCODE='55000'; END IF;
 SELECT s INTO STRICT witness FROM multa37_ddl_witness;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'functions','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(p) INTO obj FROM pg_proc p WHERE oid=(x->>0)::oid;
 IF obj IS DISTINCT FROM x->1 THEN RAISE EXCEPTION 'Postflight37 função intocada divergiu' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'relations','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(c) INTO obj FROM pg_class c WHERE oid=(x->>'oid')::oid;
 IF obj IS DISTINCT FROM x THEN RAISE EXCEPTION 'Postflight37 tabela/ACL predecessora divergiu %',x->>'relname' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'attributes','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(a) INTO obj FROM pg_attribute a WHERE attrelid=(x->>'attrelid')::oid AND attnum=(x->>'attnum')::int;
 IF obj IS DISTINCT FROM x THEN RAISE EXCEPTION 'Postflight37 coluna/ACL predecessora divergiu' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'triggers','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(t) INTO obj FROM pg_trigger t WHERE oid=(x->>'oid')::oid;
 IF obj IS DISTINCT FROM x THEN RAISE EXCEPTION 'Postflight37 trigger predecessor divergiu' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'constraints','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(k) INTO obj FROM pg_constraint k WHERE oid=(x->>'oid')::oid;
 IF obj IS DISTINCT FROM x THEN RAISE EXCEPTION 'Postflight37 constraint predecessora divergiu' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(coalesce(nullif(witness->'policies','null'::jsonb),'[]'::jsonb)) LOOP
 SELECT to_jsonb(p) INTO obj FROM pg_policy p WHERE oid=(x->>'oid')::oid;
 IF obj IS DISTINCT FROM x THEN RAISE EXCEPTION 'Postflight37 policy predecessora divergiu' USING ERRCODE='55000'; END IF;
 END LOOP;
END $post37$;

-- Reseal exclusivamente metadata de instalação, após delta permitido. Nenhuma prova financeira.
UPDATE public.legados_manifesto SET assinatura=public.legados_metadata() WHERE versao=1;
UPDATE public.multimodal_manifesto SET assinatura=public.multimodal_metadata() WHERE id=1;
UPDATE public.multa36_manifesto SET assinatura=public.multa36_metadata() WHERE id=1;
INSERT INTO public.caixa37_manifesto VALUES(1,public.caixa37_metadata());
SELECT public.caixa37_verificar();
COMMIT;
